          heading: '〔LAN システムの構成〕',
          body: 'B 主任は図1 の提案構成を作り、C 課長とレビューした。無線は、2つの 5 GHz に別々の ESSID を付けて PC を半分ずつつなぎ、2.4 GHz は 5 GHz が全く使えないときの予備と、優先度の低い端末・IoT 機器に充てる。1台あたりの速度は、20 MHz 幅の2本を d でまとめた 40 MHz 幅で満たせる見込み。監視には WLC を入れ、AP の死活・利用者の認証・端末の接続を見て、職員が WLC の画面で確かめられるようにする。認証の後の端末の通信は WLC を通さない。有線は、AP への給電はフロア L2SW の PoE で行うが、PoE+（IEEE802.3at、最大 30 W）では足りないおそれがあるので e（IEEE802.3bt）にする。フロア L2SW と AP のあいだは 1 Gbps で、PC の台数と動画の要件から量を見積もると収まる（下線③）。ただ、AP が壊れると隣の教室の PC も寄ってくるので、f（2.5GBASE-T・5GBASE-T）を考え、Wi-Fi 6E に向けて 10GBASE-T も候補にする。基幹は、負荷の高い所に 10 GbE を何本も張り、L2 はスパニングツリー、L3 は基幹 L3SW の VRRP で冗長にした。C 課長は、これでは負荷が高いとき 10 GbE が詰まりうるうえ、流れを均す設計も難しいと指摘した（下線④）。そこで B 主任は、基幹 L3SW・サーバ L2SW のそれぞれで2台を g でつないで1台として動かし、サーバ・FW・WLC・フロア L2SW へのリンクを全て、2台にまたがるリンクアグリゲーションにする案を出した（下線⑤）。DHCP サーバで WLAN 端末にアドレスを配るので基幹 L3SW に h を設定し、基幹 L3SW の既定の経路は FW へ向ける。最後に C 課長は、職員の保守の作業でブロードキャストストームを起こしうるとして、作業ミスへのループ対策を求め（下線⑥）、B 主任はどのスイッチにもループ検知を入れることを考える。\n→ 設問1 d〜h はこの節の空欄、設問3(1) は下線③と RFP の要件、(2) は下線④⑤と図1 の (i)〜(v)、(3) は下線⑥と RFP の保守の受け持ちが根拠。',
